/// Epoch-1 compiler IR wire: the six manager carriers of PROP-054 §7.4/§14.6,
/// frozen from the landed R3 domain types. One whole value of the level
/// being passed crosses per invocation (`##WHOLE-IR-WIRE`); source/document
/// are one addressed document, documents is the explicit document batch,
/// closure/lane/emitted are one complete final artifact (`##IR-LEVELS`, SPEC-
/// DEBT §8.8). The same document is the R3.4 trace snapshot — no second trace-
/// only IR shape exists. TWO metadata sets sit below and must not be confused:
/// `x-conversion-gates` is what the strict domain decoder OWES on every carrier
/// it is handed, including one a plugin transformed and returned; `x-corpus-
/// producer-oracles` is characterization of what THIS corpus's builtin passes
/// emitted. A plugin may legally return a verifier-valid closure whose anchors
/// the builtin `qualify` would have spelled differently or whose order the
/// builtin `close` would not have chosen — the decoder must accept it, and only
/// the corpus tests hold it to the builtin spelling.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "shape")]
pub enum Ir {
    #[serde(rename = "closure-artifact")]
    ClosureArtifact(Box<IrClosureArtifact>),

    #[serde(rename = "document-document")]
    DocumentDocument(Box<IrDocumentDocument>),

    #[serde(rename = "documents-artifact")]
    DocumentsArtifact(Box<IrDocumentsArtifact>),

    #[serde(rename = "emitted-artifact")]
    EmittedArtifact(Box<IrEmittedArtifact>),

    #[serde(rename = "lane-artifact")]
    LaneArtifact(Box<IrLaneArtifact>),

    #[serde(rename = "source-document")]
    SourceDocument(Box<IrSourceDocument>),
}

/// Level closure, cardinality artifact: the ordered multi-seed graph for
/// one final artifact (`ClosureIr`), including qualification/absorption/link
/// typestate and the pending source/embed snapshots.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
