/// member use ONE generated `TimingRow`, not same-shaped per-module types that
/// would need converters.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct TimingRow {
    /// Saturating sum of the encode durations.
    pub encode_total: Duration,

    /// How many events carry this pass name.
    pub invocations: u32,

    /// Exact pass name this row aggregates.
    pub pass: String,

    /// Saturating sum of the pass durations this pass name's events carry.
    pub pass_total: Duration,

    /// Saturating sum of the verify durations.
    pub verify_total: Duration,
}

/// The trace half of one command report: what the observer knows when the
/// report is built. Closed: an unknown spelling is a reader error, not a newer
/// writer — additive evolution of this record rides new object members, never
/// new status values.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum TraceReportStatus {
    #[serde(rename = "failed")]
    Failed,

    #[serde(rename = "ok")]
    Ok,

    #[serde(rename = "running")]
    Running,

    #[serde(rename = "unavailable")]
    Unavailable,
}

/// The documentation this package adapts into another language (PROP-057 §5):
/// the source's `<group>/<name>` coordinate and the semver constraint on its
/// version.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct TranslatesEntry {
    pub package: String,

    pub version: String,
}

/// The ONE generated verification-evidence member (PROP-054 §14.7, `##EVIDENCE-
/// WIRE-AND-SURFACES`): the lifecycle library produces it, the existing
/// generated `LifecycleReport` carries it, and `vibe verify --json` and
/// MCP `lifecycle_run({phase:"verify"})` return that same value — terminal
/// text is a projection, never a second assembly. `observed_at` is EXCLUDED
/// from `evidence_id`; the id is a domain-separated digest over every other
/// canonical identity and comparison member, so re-reading the same claim at
/// another wall-clock second does not mint a new identity. The relational laws
/// JTD cannot express are named in `x-relational-laws` and enforced by the
/// hand-written validator in `vibe-wire/src/behaviour/verification_evidence/`;
/// the two label sets are pinned equal by a wire test, so an undocumented law
/// and an unimplemented label are both red — the seam the compile-trace member
/// already carries.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct VerificationEvidence {
    /// The artifact comparison rows, in canonical row order. Explicit even when
    /// empty, for the same reason `inputs` is.
    pub artifacts: Vec<ArtifactWitness>,

    /// The evidence wire epoch — 1 today. A reader that does not know the
    /// number stops rather than guessing at the members.
    pub evidence: u32,

    /// `sha256:` followed by 64 lowercase hex over every canonical identity
    /// and comparison member EXCEPT `observed_at`. Two reads of the same claim
    /// carry the same id; a claim about another tuple carries another one.
    pub evidence_id: String,

    /// The declared-input comparison rows, in canonical row order. Explicit
    /// even when empty — an empty evidence set is the `unavailable` root, said
    /// out loud.
    pub inputs: Vec<InputMeasurement>,

    /// When the comparison was performed. Excluded from `evidence_id` on
    /// purpose: the clock is an input, not part of what was measured.
    pub observed_at: Timestamp,

    /// The run this comparison was observed under.
    pub run: EvidenceRun,

    /// The overall comparison outcome — the worst row, never an independent
    /// verdict, and never the command's own `ok` (a verify handler may fail
    /// while the identity matched).
    pub status: EvidenceStatus,
}

/// Semantic version string — `semver::Version` in code.
pub type Version = semver::Version;

/// Per-version catalog record (PROP-005 §2.6) — one line of `primary.jsonl`,
/// one element of a `by-name` candidate's `versions[]`, one `POST /v1/packages`
/// body. Shared as a vocabulary because `by_name` and `journal` carry it
/// transitively and JTD has no cross-file refs (G9).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct VersionEntry {
    pub content_hash: String,

    pub files_count: u32,

    pub group: Group,

    pub indexed_at: Timestamp,

    pub indexed_by: String,

    pub kind: PackageKind,

    pub name: String,

    pub registry: String,

    pub schema_version: u32,

    pub source_ref: String,

    pub source_url: String,

    pub version: Version,

    /// The four answers a reader needs before opening anything — what it
    /// covers, for whom, what it assumes known, what it leaves out (PROP-057
    /// §7); absent when the package declares none.
    #[serde(rename = "abstract")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub abstract_: Option<String>,

    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub authors: Vec<String>,

    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub boot_snippet: Option<BootSnippetEntry>,

    /// True when this package is an authored bridge around separately licensed
    /// upstream content.
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub bridge: bool,

    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub compatibility: Option<CompatibilityEntry>,

    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub conflicts: Option<ConflictsEntry>,

    /// PURL of the package this record describes; absent when unbound.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub describes: Option<String>,

    /// Human-readable summary; absent when the package declares none.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,

    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub documentation: Option<DocumentationEntry>,

    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub documents: Vec<DocumentsEntry>,

    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub embedded_sources: Vec<EmbeddedSourceEntry>,

    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub features: Option<FeaturesEntry>,

    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub frozen: bool,

    /// Project URL; absent when the package declares none.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub homepage: Option<String>,

    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub i18n: Option<I18nEntry>,

    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub keywords: Vec<String>,

    /// SPDX expression; absent when the package declares none.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub license: Option<String>,

    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub media: Option<MediaEntry>,

    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub must_understand: Vec<String>,

    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub obsoletes: Option<ObsoletesEntry>,

    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub provides: Option<ProvidesEntry>,

    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub requires: Option<RequiresEntry>,

    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub requires_any: Vec<RequiresAnyEntry>,

    /// Commit the ref resolved to at publish time; absent for non-git sources.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub resolved_commit: Option<String>,

    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub subskills: Vec<SubskillEntry>,

    /// Display name of the package (PROP-057 §7); absent when the package
    /// declares none. Required in the manifest of a `doc` package, optional for
    /// every other kind.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,

    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub translates: Option<TranslatesEntry>,

    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub workspace_origin: Option<WorkspaceOriginEntry>,

    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub yanked: bool,
}

/// `[origin]` projection (PROP-007 §2.8): provenance of a copy published from
/// a workspace member. `generated_at` is a plain ISO-8601 string in code, not a
/// domain timestamp.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct WorkspaceOriginEntry {
    pub generated_at: String,

    pub generated_by: String,

    pub path: String,

    pub upstream: String,

    /// Workspace HEAD the copy was generated from; absent for an uncommitted
    /// tree.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub commit: Option<String>,
}

/// The lockfile, dependency root and selected packages visible to a lifecycle
/// or native handler.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct World {
    pub deps_root: String,

    pub lockfile: String,

    /// Selected reachable packages in canonical lockfile order.
    pub packages: Vec<WorldPackage>,
}

/// One selected package in the resolved lifecycle world.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct WorldPackage {
    pub group: String,

    pub kind: String,

    pub name: String,

    pub slot: String,

    pub version: String,
}
